def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter

    counts = Counter(v for row in grid for v in row)
    # The marker is the least frequent color.
    marker = min(counts, key=counts.get)
    pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == marker]

    # Normalize and generate rotations/reflections of the marker shape.
    def normalize(points):
        mr = min(r for r, c in points)
        mc = min(c for r, c in points)
        return frozenset((r - mr, c - mc) for r, c in points)

    shapes = set()
    for flip in (1, -1):
        for k in range(4):
            transformed = []
            for r, c in pts:
                c *= flip
                for _ in range(k):
                    r, c = c, -r
                transformed.append((r, c))
            shapes.add(normalize(transformed))

    out = [row[:] for row in grid]
    for shape in shapes:
        sh = max(r for r, c in shape) + 1
        sw = max(c for r, c in shape) + 1
        for r0 in range(h - sh + 1):
            for c0 in range(w - sw + 1):
                cells = [(r0 + r, c0 + c) for r, c in shape]
                if all(grid[r][c] == 0 for r, c in cells):
                    for r, c in cells:
                        out[r][c] = marker
    return out
